// Pacing pass: global camera reframes (punch-ins, detail cuts, pushes) and detail inserts inside long holds.
// Driven by data/pace.json, generated by PROJECTS/BINANCE_HEIST/scripts/pace_plan.py from the rendered v1.
// Outside the listed windows the transform is identity, so every other frame renders exactly as before.
import React from 'react';
import { AbsoluteFill, useCurrentFrame } from 'remotion';
import PACE from '../data/pace.json';
import { At } from '../lib/frame';
import { clamp, outExpo } from '../lib/anim';
import { GlitchBars } from './core';
import { INSERTS } from './inserts';

type Key = { f: number; s: number; tx: number; ty: number; ease: number };
type Ins = { name: string; f0: number; f1: number };
const KEYS = (PACE as { cams: Key[] }).cams;
const INS = (PACE as { inserts: Ins[] }).inserts;

// Pre-compute each key's start state (the previous key's target).
const STARTS: { s: number; tx: number; ty: number }[] = [];
KEYS.forEach((k, i) => STARTS.push(i === 0 ? { s: 1, tx: 0, ty: 0 } : { s: KEYS[i - 1].s, tx: KEYS[i - 1].tx, ty: KEYS[i - 1].ty }));

const camAt = (f: number) => {
  let lo = 0;
  let hi = KEYS.length - 1;
  let idx = -1;
  while (lo <= hi) {
    const m = (lo + hi) >> 1;
    if (KEYS[m].f <= f) {
      idx = m;
      lo = m + 1;
    } else hi = m - 1;
  }
  if (idx < 0) return { s: 1, tx: 0, ty: 0, drift: 0 };
  const k = KEYS[idx];
  const a = STARTS[idx];
  const p = k.ease > 0 ? outExpo(clamp((f - k.f) / k.ease, 0, 1)) : 1;
  const s = a.s + (k.s - a.s) * p;
  return { s, tx: a.tx + (k.tx - a.tx) * p, ty: a.ty + (k.ty - a.ty) * p, drift: k.s > 1.01 ? (f - k.f) / 30 : 0 };
};

export const PaceCam: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const f = useCurrentFrame();
  const c = camAt(f);
  const ident = Math.abs(c.s - 1) < 1e-4 && Math.abs(c.tx) < 0.01 && Math.abs(c.ty) < 0.01;
  const d = 1 + 0.006 * c.drift;
  return (
    <AbsoluteFill style={{ overflow: 'hidden' }}>
      <AbsoluteFill style={ident ? undefined : { transform: `scale(${d})`, transformOrigin: '50% 45%' }}>
        <AbsoluteFill style={ident ? undefined : { transform: `translate(${c.tx}px, ${c.ty}px) scale(${c.s})`, transformOrigin: '0 0' }}>{children}</AbsoluteFill>
      </AbsoluteFill>
      {INS.map((i) => {
        const Comp = INSERTS[i.name];
        if (!Comp || f < i.f0 - 1 || f > i.f1 + 1) return null;
        return (
          <At key={`${i.name}${i.f0}`} from={i.f0} len={i.f1 - i.f0 + 1}>
            <AbsoluteFill style={{ background: '#07080B' }}>
              <Comp />
              <GlitchBars f={f} amount={Math.max(0, 1 - (f - i.f0) / 4) * 0.9} seed={`ins${i.f0}`} />
            </AbsoluteFill>
          </At>
        );
      })}
    </AbsoluteFill>
  );
};
